const {chromium}=require('playwright');const F='file://'+process.argv[2];const S=process.argv[3];
const ok=(c,m)=>console.log((c?'PASS ':'FAIL ')+m);
(async()=>{const b=await chromium.launch();const p=await b.newPage({viewport:{width:1440,height:900}});const e=[];p.on('pageerror',x=>e.push(x.message));
await p.goto(F);await p.evaluate(()=>{localStorage.clear();localStorage.setItem('scopeline-chat-v1',JSON.stringify({features:[],view:'home',mode:'steps'}))});await p.reload();await p.waitForTimeout(400);
ok(await p.locator('.squad .avi').count()===4,'squad row has 4 illustrated avatars');
ok(await p.locator('.nametag .avi').count()===4,'solution name tags use the same avatars');
ok(await p.locator('.phone').count()===1,'design review panel shows a phone screen');
await p.evaluate(()=>document.querySelector('.top').style.position='static');
await p.evaluate(()=>document.getElementById('how-it-works').scrollIntoView({block:'center'}));
await p.waitForTimeout(13500);ok(await p.locator('#hsteps li.on[data-hstep="5"]').count()===1,'story reaches step 5 (hand off)');
await p.locator('#how-it-works').screenshot({path:S+'/how-5.png'});
await p.waitForTimeout(8000);ok(await p.locator('#h-res.saved').count()===1||await p.locator('#hwin.hplaying').count()===0,'story ends with the decision saved');
await p.locator('#how-it-works').screenshot({path:S+'/how-6.png'});
await p.click('#hsteps li[data-hstep="6"]');await p.waitForTimeout(300);ok(await p.locator('#hsteps li.on[data-hstep="6"]').count()===1,'clicking a step jumps to it');
ok(await p.locator('.tip').count()===6,'six habits section');
await p.locator('#results').screenshot({path:S+'/results.png'});
await p.click('[data-try="next"]');await p.waitForSelector('.m-ai');
ok((await p.locator('.m-ai').first().textContent()).includes('After you agree and share'),'asking for next steps answers with owner-by-owner steps');
await p.locator('.dock .chip',{hasText:'Next steps'}).click();await p.waitForFunction(()=>document.querySelectorAll('.m-ai').length>=2);
ok((await p.locator('.m-ai').last().textContent()).includes('keep the test you agreed'),'Next steps chip works mid-chat');
const m=await b.newPage({viewport:{width:390,height:844}});await m.goto(F);await m.waitForTimeout(400);
ok(!(await m.evaluate(()=>document.documentElement.scrollWidth>innerWidth)),'fits a phone');
ok(e.length===0,'no errors '+e.join('; '));await b.close();})();
